volatile unsigned long pulseCount = 0;
const float CALIBRATION_FACTOR = 7.5; // Hz per L/min
const int FLOW_PIN = 2;
const int LED_PIN = 13;

void flowPulse() {
  pulseCount++;
  digitalWrite(LED_PIN, !digitalRead(LED_PIN));
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  pinMode(FLOW_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(FLOW_PIN), flowPulse, RISING);
  Serial.println("YF-S201 Water Flow Meter");
  Serial.println("========================");
}

void loop() {
  unsigned long count;
  noInterrupts();
  count = pulseCount;
  interrupts();

  float flowRate = count / CALIBRATION_FACTOR;
  float totalML = flowRate * (millis() / 60000.0);

  Serial.print("Flow: ");
  Serial.print(flowRate, 2);
  Serial.print(" L/min  |  Total: ");
  Serial.print(totalML, 1);
  Serial.println(" mL");

  delay(500);
}
